import xarray as xr
import numpy as np
import pandas as pd

def test_dataset_interp_datetime():
    # Create a dataset with a numeric array and a datetime array
    times = pd.date_range("2000-01-01", periods=3)
    x = np.arange(3)
    ds = xr.Dataset(
        {
            "numeric": (("x"), [1.0, 2.0, 3.0]),
            "datetime": (("x"), times),
        },
        coords={"x": x},
    )

    print("Dataset:\n", ds)

    try:
        # Interpolate onto new x coordinates
        ds_interp = ds.interp(x=[0.5, 1.5])
        print("\nInterpolated Dataset:\n", ds_interp)
        if "datetime" not in ds_interp.variables:
            print("\nBUG: 'datetime' variable was silently dropped!")
    except TypeError as e:
        print("\nCaught expected TypeError:", e)
    except Exception as e:
        print("\nCaught unexpected exception:", type(e), e)

def test_dataarray_interp_datetime():
    times = pd.date_range("2000-01-01", periods=3)
    x = np.arange(3)
    da = xr.DataArray(times, coords={"x": x}, dims=("x",))

    print("\nDataArray:\n", da)

    try:
        da.interp(x=[0.5, 1.5])
        print("\nBUG: DataArray.interp did not raise TypeError for datetime!")
    except TypeError as e:
        print("\nCaught expected TypeError:", e)
    except Exception as e:
        print("\nCaught unexpected exception:", type(e), e)

if __name__ == "__main__":
    test_dataset_interp_datetime()
    test_dataarray_interp_datetime()

